from collections import deque
seed=[(r,c) for r,row in enumerate(a) for c,v in enumerate(row) if v==4]
seen=set(seed); q=deque(seed)
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 0<=rr<len(a) and 0<=cc<len(a[0]) and (rr,cc) not in seen and a[rr][cc]==0:
   seen.add((rr,cc));q.append((rr,cc))
actual={(r,c) for r in range(len(a)) for c in range(len(a[0])) if b[r][c]==4}
print(len(seen),len(actual),len(seen-actual),len(actual-seen))
print('extra',sorted(actual-seen)[:30]);print('miss',sorted(seen-actual)[:30])

zeros={(r,c) for r in range(25) for c in range(21) if a[r][c]==0}; comps=[]
while zeros:
 st=zeros.pop(); comp={st}; q=[st]
 while q:
  r,c=q.pop()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   p=(r+dr,c+dc)
   if p in zeros: zeros.remove(p);comp.add(p);q.append(p)
 comps.append(comp)
print(len(comps),sorted([len(c) for c in comps],reverse=True)[:30])
for c in sorted(comps,key=len,reverse=True)[:20]:
 n=len(c&actual); print(len(c),n, 'all?',n==len(c), 'partial', n>0)
